css:
.d-hp{box-sizing:border-box;width:300px;max-width:100%;height:150px;overflow-x:hidden;overflow-y:auto;border:1px solid var(--line);border-radius:10px;background:var(--bg)}
.d-hp-space{height:540px}
.d-hp-pin{position:sticky;top:0;height:148px;display:flex;align-items:center}
.d-hp-track{display:flex;width:900px;animation:d-scroll-horizontal-pin-x linear both;animation-timeline:scroll(nearest)}
.d-hp-panel{flex:0 0 300px;box-sizing:border-box;height:148px;display:flex;align-items:center;justify-content:center;border-right:1px solid var(--line);font-size:15px;color:var(--muted);background:var(--bg)}
.d-hp-panel:nth-child(odd){background:var(--paper);color:var(--ink)}
.d-hp:focus-visible{outline:1px solid var(--ink);outline-offset:2px}
@keyframes d-scroll-horizontal-pin-x{from{transform:translateX(0)}to{transform:translateX(-600px)}}
